package StoreTest;

import Plugin_ERP.Tests.LoginTest.BaseTest;
import Plugin_ERP.System_Modules.Login.Coverage.ScreenPage;
import TestSupport.BasicDataFixtures;
import java.math.BigDecimal;
import java.time.Duration;
import java.util.*;
import org.openqa.selenium.By;
import org.openqa.selenium.support.ui.WebDriverWait;
import org.testng.Assert;
import org.testng.annotations.*;

/** Adjustments are generated by closing a stocktaking; their screens are read only. */
public abstract class AdjustmentCoverageScenario extends BaseTest {
    protected abstract String endpoint();
    protected abstract String route();
    protected abstract int stockDirection();
    protected abstract String title();
    private StoreTestData refs;
    private BasicDataFixtures documents;
    private ScreenPage page;
    private StoreTestData.Record item;
    private Map<String,Object> adjustment;
    private BigDecimal expected;
    private boolean closeAttempted;

    @BeforeClass(alwaysRun=true) public void closeOwnedStocktakingThroughUi() {
        requirePreparedSession();
        refs=new StoreTestData(driver); documents=new BasicDataFixtures(driver); page=new ScreenPage(driver);
        refs.beginScenario();documents.beginScenario(); item=refs.item(1);
        BigDecimal before=new BigDecimal(refs.balance(item,1).toString());
        expected=before.add(new BigDecimal("1.25").multiply(BigDecimal.valueOf(stockDirection())));
        String marker=documents.reserveName("Stocktakings","close-for-"+endpoint());
        page.open("inventory/new","انشاء محضر جديد");documents.installCapture();
        page.choose("المخزن",refs.store(1).name());page.notes(marker);page.addItem(item.name());
        page.tableLine(item.name(),"الرصيد الفعلي",expected.toPlainString());page.click("حفظ");
        page.visibleElement(By.cssSelector(".swal2-cancel"));page.confirm(true);
        var draft=documents.awaitSaved("Stocktakings",marker);
        var stored=documents.read(draft);Assert.assertEquals(stored.get("storeId"),refs.store(1).id());
        page.dismissSuccess();page.open("inventory","محضر الجرد");
        page.rowAction(stored.get("code").toString(),"close");
        closeAttempted=true;
        page.click(By.cssSelector(".modal.show button[data-action-type='save']"));page.confirm(true);
        new WebDriverWait(driver,Duration.ofSeconds(40)).until(d->Boolean.TRUE.equals(documents.read(draft).get("isComplete")));
        refs.awaitOriginalSession();
        new WebDriverWait(driver,Duration.ofSeconds(30)).until(d->new BigDecimal(refs.balance(item,1).toString()).compareTo(expected)==0);
        adjustment=new WebDriverWait(driver,Duration.ofSeconds(30)).withMessage("Generated adjustment for the owned stocktaking was not found")
                .until(d->findGeneratedAdjustment(marker));
        io.qameta.allure.Allure.addAttachment("Closed stocktaking and generated adjustment", "application/json",
                new org.json.JSONObject(BasicDataFixtures.fields("stocktaking",documents.read(draft),"adjustment",adjustment)).toString(),".json");
    }

    @SuppressWarnings("unchecked") private Map<String,Object> findGeneratedAdjustment(String marker) {
        Object response=documents.query(endpoint()+"?storeId="+refs.store(1).id()+"&pageNumber=1&pageSize=500");
        if (!(response instanceof Map<?,?> result) || !(result.get("pageData") instanceof List<?> rows))
            throw new AssertionError("Unexpected generated adjustment response");
        List<Map<String,Object>> matches=new ArrayList<>();
        for(Object value:rows) {
            if(!(value instanceof Map<?,?> summary)||summary.get("id")==null)continue;
            // List projections may omit storeId; verify the detail rather than dropping the row.
            if(summary.get("storeArabicName")!=null&&!refs.store(1).name().equals(summary.get("storeArabicName")))continue;
            var detail=documents.read(new BasicDataFixtures.Record(endpoint(),summary.get("id"),marker,Map.of()));
            if(detail!=null&&refs.store(1).id().equals(detail.get("storeId")))matches.add(detail);
        }
        if(matches.size()>1)throw new AssertionError("Multiple generated adjustments matched the fresh owned store");
        return matches.isEmpty()?null:matches.getFirst();
    }

    private void openDetail() { page.open(route()+"/edit/"+adjustment.get("id"),title()); }
    @Test public void generatedFractionalAdjustmentMatchesOwnedItemAndStock() {
        var lines=(List<?>)adjustment.get("lines");Assert.assertEquals(lines.size(),1);
        var line=(Map<?,?>)lines.getFirst();Assert.assertEquals(line.get("itemId"),item.id());
        Assert.assertEquals(new BigDecimal(line.get("quantity").toString()).abs().compareTo(new BigDecimal("1.25")),0);
        openDetail();Assert.assertTrue(page.bodyText().contains(item.name()));
        Assert.assertEquals(new BigDecimal(refs.balance(item,1).toString()).compareTo(expected),0);
    }
    @Test public void adjustmentScreenDoesNotOfferIndependentCreationOrDeletion() {
        page.open(route(),stockDirection()<0?"تسوية العجز":"تسوية الفائض");
        Assert.assertFalse(page.visible(By.cssSelector("button[data-action-type='new'],button[data-action-type='delete']")));
        page.click(By.xpath("//tr[@data-pk="+ScreenPage.literal(adjustment.get("id").toString())+"]//button[.//*[local-name()='svg' and contains(@class,'feather-tv')]]"));
        new WebDriverWait(driver,Duration.ofSeconds(25)).until(d->d.getCurrentUrl().contains(adjustment.get("id").toString())
                &&page.bodyText().contains(item.name()));
        Assert.assertFalse(page.visible(By.cssSelector("button[data-action-type='save']")));
    }
    @Test public void reopeningAdjustmentDoesNotPostStockAgain() {
        openDetail();openDetail();Assert.assertTrue(page.bodyText().contains(item.name()));
        Assert.assertEquals(new BigDecimal(refs.balance(item,1).toString()).compareTo(expected),0);
    }
    @AfterClass(alwaysRun=true) public void retainClosedInventoryAuditOrCleanDraft() {
        if (closeAttempted) {
            // These documents represent posted inventory history and must not be deleted.
            try { documents.preserveAuditHistory("inventory-audit-documents"); }
            finally { refs.preserveInventoryAuditHistory(); }
        } else {
            if(documents!=null)documents.close();if(refs!=null)refs.close();
        }
    }
}
